import{_ as r,a0 as o,w as p,s as m,ao as l,I as s,x as i,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"10 款你可以通過 Wine 在 Linux 上玩的遊戲 | LCTT x X-CMD","titleTemplate":false,"description":"10 款你可以通過 Wine 在 Linux 上玩的遊戲 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10 款你可以通過 Wine 在 Linux 上玩的遊戲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10 款你可以通過 Wine 在 Linux 上玩的遊戲 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20171005 10 Games You Can Play on Linux with Wine","title":"10 款你可以通過 Wine 在 Linux 上玩的遊戲","tag":"201903","desc":""},"relativePath":"201903/20171005 10 Games You Can Play on Linux with Wine.md","filePath":"[post].md"}'),u={name:"201903/20171005 10 Games You Can Play on Linux with Wine.md"};function d(h,e,w,W,x,g){const a=o("Link");return p(),m("div",null,[e[19]||(e[19]=l('<h1 id="_10-款你可以通過-wine-在-linux-上玩的遊戲" tabindex="-1">10 款你可以通過 Wine 在 Linux 上玩的遊戲 <a class="header-anchor" href="#_10-款你可以通過-wine-在-linux-上玩的遊戲" aria-label="Permalink to “10 款你可以通過 Wine 在 Linux 上玩的遊戲”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/wine-games-feat.jpg" alt=""></p><p>Linux <em>確實</em> 能玩遊戲，而且還能玩不少遊戲。獨立遊戲在 Linux 平台上蓬勃發展，頂級的獨立遊戲也常常會在發售首日便發佈 Linux 版本。然而，3A 遊戲大作的開發者們卻常常忽略 Linux，所以你不會很快就能玩上身邊朋友們談論正火的那些遊戲。</p><p>但情況還沒有糟透。Wine —— 一個能使 Windows 應用在類似 Linux、BSD 和 OS X 上運行的兼容層，在支持的遊戲數量和性能表現上都取得了巨大進步。很多遊戲大作都可以在 Wine 的支持下運行。你不能完全釋放本機性能，但還是可以跑起來遊戲，運行也還算流暢，當然這也要取決與你的系統配置。下面我們來盤點一下這些可能會令你大吃一驚的可以通過 Wine 在 Linux 上玩的遊戲。（LCTT 譯註：本文原文發表於 2017 年，有些信息可能有所過時。）</p><h3 id="_10、魔獸世界" tabindex="-1">10、魔獸世界 <a class="header-anchor" href="#_10、魔獸世界" aria-label="Permalink to “10、魔獸世界”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/wow.jpg" alt="World of Warcraft Wine" title="World of Warcraft Wine"></p><p>這款經典的 MMORPG 之王仍舊堅挺並保持活力。雖然這不是一款以畫面見長的遊戲，但想要開到全畫質也需要費一些功夫。魔獸世界已經在 Wine 的支持下運行了很多年。到了最新資料片發佈時，魔獸世界為它的 Mac 版本提供了 OpenGL 支持，使得遊戲也可以很輕鬆地在 Linux 下運行。這已經不再是個問題了。</p>',7)),s("p",null,[e[1]||(e[1]=i("你需要通過 DX9 來運行遊戲並從 ",-1)),t(a,{href:"https://www.maketecheasier.com/install-wine-gallium-nine-linux"},{default:n(()=>[...e[0]||(e[0]=[i("Gallium Nine",-1)])]),_:1}),e[2]||(e[2]=i(" 補丁來獲得一些性能提升，不過你也可以放心大膽地在 Linux 中下副本了。",-1))]),e[20]||(e[20]=l('<h3 id="_9、上古卷軸-5-天際" tabindex="-1">9、上古卷軸 5：天際 <a class="header-anchor" href="#_9、上古卷軸-5-天際" aria-label="Permalink to “9、上古卷軸 5：天際”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/skyrim.jpg" alt="Skyrim Wine" title="Skyrim Wine"></p><p>上古卷軸 5 已經不是款新遊戲了，但它的 mod 社區依舊活躍。如果你的 Linux 系統有足夠資源的話，你可以很輕鬆地加上很多很多 mod。需要記住的是 Wine 運行時要比遊戲佔用更多的系統資源，所以使用 mod 時也要考慮這一點。</p><h3 id="_8、星際爭霸-ii" tabindex="-1">8、星際爭霸 II <a class="header-anchor" href="#_8、星際爭霸-ii" aria-label="Permalink to “8、星際爭霸 II”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/sc2.jpg" alt="StarCraft II Wine" title="StarCraft II Wine"></p><p>星際爭霸 II 是成為市場上最受歡迎的 RTS 遊戲之一，並且在 Wine 下運作良好。它實際上也是 Wine 下表現最好的遊戲之一。</p><p>考慮到這款遊戲本身的競技性，你當然希望遊戲能夠流暢地運行。不過不用擔心，只要你的硬件夠用就絕對沒問題。</p><p>這是一個你可以從 “staging” 補丁獲益的例子，所以在你設置遊戲時請繼續使用它們。</p><h3 id="_7、輻射-3-輻射-新維加斯" tabindex="-1">7、輻射 3 / 輻射：新維加斯 <a class="header-anchor" href="#_7、輻射-3-輻射-新維加斯" aria-label="Permalink to “7、輻射 3 / 輻射：新維加斯”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/Fallout_3.jpg" alt="Fallout 3 Wine" title="Fallout 3 Wine"></p><p>在你提問之前，輻射 4 已經很快就準備就緒，也許就在你正讀這篇文章的時候就可以玩了。就目前而言，輻射 3 和 輻射：新維加斯都能在有沒有 mod 的情況下良好運行。這些遊戲在 Wine 下運行地非常好，甚至還能加載大量 mod 來保持遊戲的新鮮性和趣味性。在輻射 4 獲得全面支持前玩這些舊作也不算是個很大的妥協。</p><h3 id="_6、doom-2016" tabindex="-1">6、Doom (2016) <a class="header-anchor" href="#_6、doom-2016" aria-label="Permalink to “6、Doom (2016)”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/doom.jpg" alt="Doom Wine" title="Doom Wine"></p><p>Doom（毀滅戰士）是過去幾年中最刺激的射擊遊戲之一。在 Wine 支持下並加載 “staging” 補丁可以流暢地運行最新版本。單人模式和多人模式都有很棒的遊戲體驗，而且也不需要花費大量時間來配置 Wine 和調整設置。所以你想在 Linux 上體驗 3A 級射擊遊戲的話，不妨嘗試一下 Doom 。</p><h3 id="_5、激戰-2" tabindex="-1">5、激戰 2 <a class="header-anchor" href="#_5、激戰-2" aria-label="Permalink to “5、激戰 2”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/gw2.jpg" alt="Guild Wars 2 Wine" title="Guild Wars 2 Wine"></p><p>激戰 2 是一款無月卡（買斷制）的融合了多人和迷宮探險元素的遊戲。它在市場上很受歡迎，並自稱在遊戲中有着很多創新。你同樣可以通過 Wine 在 Linux 上玩到這款遊戲。</p><p>激戰 2 也不算一款很老的 MMO 遊戲。它試圖以圖像表現來保持現代風格，並具有着相當高分辨率的紋理和視覺效果。所有這些特點都能在 Wine 下順利運行。</p><h3 id="_4、英雄聯盟" tabindex="-1">4、英雄聯盟 <a class="header-anchor" href="#_4、英雄聯盟" aria-label="Permalink to “4、英雄聯盟”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/League_of_legends.jpg" alt="League Of Legends Wine" title="League Of Legends Wine"></p><p>在 MOBA 遊戲的世界中有兩個強者：DoTA2 和英雄聯盟。Valve 已經將 DoTA2 移植到 Linux 上很久了，但玩家們卻從沒在 Linux 上玩過英雄聯盟。如果你是 Linux 的使用者並熱衷英雄聯盟，你還是可以通過 Wine 來玩這款你最愛的 MOBA 遊戲。</p><p>英雄聯盟是個很有趣的例子。它的遊戲本身運行良好，但安裝程序卻會因為需要 Adobe Air 而中斷。一些安裝程序腳本例如 Lutris 和 PlayOnLinux 能幫你通過這一步驟。一旦安裝完畢，你就可以毫無困難地運行遊戲，甚至在激烈的戰況中依舊暢快玩耍。</p><h3 id="_3、爐石傳説" tabindex="-1">3、爐石傳説 <a class="header-anchor" href="#_3、爐石傳説" aria-label="Permalink to “3、爐石傳説”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/HearthStone.jpg" alt="HearthStone Wine" title="HearthStone Wine"></p><p>爐石傳説是一款流行且令人上癮的免費卡牌遊戲，你可在各種平台上來一局……除了 Linux。不過別擔心，在 Wine 中你可以輕鬆玩到這款遊戲。爐石並不大，所以即使在最低配置的系統裏也都能玩，這是個好消息。不過由於它的競技性所以還是要對遊戲性能有一定要求。</p><p>玩爐石不需要任何特殊配置和補丁，直接開玩！</p><h3 id="_2、巫師-3" tabindex="-1">2、巫師 3 <a class="header-anchor" href="#_2、巫師-3" aria-label="Permalink to “2、巫師 3”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/witcher3.jpg" alt="Witcher 3 Wine" title="Witcher 3 Wine"></p><p>你不是唯一一個對在這份榜單中看到了巫師 3 而感到吃驚的人。在最新版 “stage” 補丁的支持下，你終於可以在 Linux 中體驗這款遊戲了。儘管最初承諾會有原生版本，但 Linux 玩家還是等了很久才迎來了巫師系列的第三部。</p><p>不過最好不要指望一切都能完美運行。巫師 3 <em>剛剛</em> 得到支持，有些內容可能還不會達到預期。也就是説，如果你只能用 Liux 來玩遊戲，並且願意處理一些問題。那麼你也可以享受到這款完美遊戲帶來的初體驗了。</p><h3 id="_1、守望先鋒" tabindex="-1">1、守望先鋒 <a class="header-anchor" href="#_1、守望先鋒" aria-label="Permalink to “1、守望先鋒”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2017/09/Overwatch.jpg" alt="Overwatch Wine" title="Overwatch Wine"></p><p>最後，讓我們來談談 Linux 玩家心中的另一個“白鯨”。很多人認為守望先鋒會像大多數暴雪遊戲一樣，在發售當日就能在 Wine 上獲得支持。不過情況非常不同，因為守望先鋒只支持 DX11，這也正是 Wine 面臨的一個痛點。</p><p>守望先鋒目前還不能擁有最佳性能表現，但是你還是可以通過裝有特殊補丁的 Wine 和包括“staging”在內的一系列定製補丁包來運行遊戲。這也説明了 Linux 玩家們真的很渴望遊玩這款遊戲，以至於自己開發了一套補丁來為它提供支持。</p><p>這份榜單當然會遺漏一些其他遊戲。大多數是由於受歡迎程度或只能從 Wine 中得到有限的支持。其他暴雪遊戲，如“風暴英雄”和“暗黑破壞神 3”也能很好地運行，但這樣來寫就會使暴雪遊戲霸佔這份榜單，這不是我們想突出的重點。</p>',35)),s("p",null,[e[4]||(e[4]=i("如果你正打算玩以上任一款遊戲，請使用 Wine 的 ",-1)),t(a,{href:"https://www.maketecheasier.com/install-wine-gallium-nine-linux"},{default:n(()=>[...e[3]||(e[3]=[i("Gallium Nine",-1)])]),_:1}),e[5]||(e[5]=i(" 版本並裝載“staging”補丁，否則遊戲可能無法正常運行。“staging”中裝載的最新補丁和提升要比正式的 Wine 發行版提供的內容要早很多，使用它會令你在性能上處於領先地位。",-1))]),e[21]||(e[21]=s("p",null,"説到進步，Wine 目前在對 DirectX11 的支持有了很大進步。對於 Windows 玩家這可能不算什麼，但對於 Linux 玩家來説絕對算是一件大事。大多數遊戲新作支持 DX11 和 DX12，而最新版本的 Wine 仍只是支持 DX9。有了 DX11 的支持，Wine 將會讓很多過去無法在 Linux 上玩的遊戲運行起來。所以，定期查看你最喜歡的 Windows 遊戲是否也可以開始在 Wine 上運行，你可能會非常驚喜。",-1)),e[22]||(e[22]=s("hr",null,null,-1)),s("p",null,[e[7]||(e[7]=i("via: ",-1)),t(a,{href:"https://www.maketecheasier.com/games-play-on-linux-with-wine/"},{default:n(()=>[...e[6]||(e[6]=[i("https://www.maketecheasier.com/games-play-on-linux-with-wine/",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=i("作者：",-1)),t(a,{href:"https://www.maketecheasier.com/author/nickcongleton/"},{default:n(()=>[...e[8]||(e[8]=[i("Nick Congleton",-1)])]),_:1}),e[12]||(e[12]=i(" 譯者：",-1)),t(a,{href:"https://github.com/Modrisco"},{default:n(()=>[...e[9]||(e[9]=[i("Modrisco",-1)])]),_:1}),e[13]||(e[13]=i(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[10]||(e[10]=[i("wxy",-1)])]),_:1})]),s("p",null,[e[16]||(e[16]=i("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[14]||(e[14]=[i("LCTT",-1)])]),_:1}),e[17]||(e[17]=i(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:n(()=>[...e[15]||(e[15]=[i("Linux中國",-1)])]),_:1}),e[18]||(e[18]=i(" 榮譽推出",-1))])])}const T=r(u,[["render",d]]);export{k as __pageData,T as default};
